#include <vector>
#include <omp.h>

/* Compute the prefix sum of the vector x into output.
   Use OpenMP to compute in parallel.
   Example:

   input: [1, 7, 4, 6, 6, 2]
   output: [1, 8, 12, 18, 24, 26]
*/
void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    const int max_threads = omp_get_max_threads();
    std::vector<double> block_sums(static_cast<std::size_t>(max_threads), 0.0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        // Block partition for this team size
        const std::size_t start = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(nt);
        const std::size_t end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(nt);

        // 1) Local prefix sum within each thread's block
        double local_sum = 0.0;
        for (std::size_t i = start; i < end; ++i) {
            local_sum += x[i];
            output[i] = local_sum;
        }

        // Store this block's total (one unique slot per thread)
        block_sums[static_cast<std::size_t>(tid)] = local_sum;

        #pragma omp barrier

        // 2) Single thread computes offsets for each block
        #pragma omp single
        {
            double offset = 0.0;
            for (int t = 0; t < nt; ++t) {
                const double s = block_sums[static_cast<std::size_t>(t)];
                block_sums[static_cast<std::size_t>(t)] = offset; // convert total -> offset
                offset += s;
            }
        }

        #pragma omp barrier

        // 3) Add block offset to each element in this block
        const double add = block_sums[static_cast<std::size_t>(tid)];
        for (std::size_t i = start; i < end; ++i) {
            output[i] += add;
        }
    }
}
